from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import sqlite3
import tempfile
import unittest
from unittest.mock import patch

import config
import public_api_data
import uniclubs_database
import uniclubs_export


NOW = datetime(2026, 11, 21, 12, 0, tzinfo=timezone.utc)
STAMP = '2026-11-21T11:00:00.000000Z'
NEXT_STAMP = '2026-11-21T11:30:00.000000Z'
FETCH_TARGET = 'uniclubs_feed.importers.fetch_public_uniclubs_feed'
CLUB_URL = 'https://uniclubs.ch/hsg/clubs/example'


def public_snapshot(observed=STAMP):
    """Return a complete fictional public JSON document with nonconsecutive local IDs."""
    return {
        '_meta': {'schema_version': 1, 'ai_citation': 'Synthetic public API test fixture.',
                  'source_url': config.UNICLUBS_EVENTS_URL, 'last_success_utc': observed},
        'clubs': [{'id': 7, 'external_id': 'club-1', 'name': 'Example Club',
                   'source_url': CLUB_URL}],
        'events': [{
            'id': 37, 'external_id': 'event-1', 'club_id': 7, 'title': 'Example workshop',
            'start_utc': '2026-11-22T11:00:00.000000Z',
            'end_utc': '2026-11-22T12:00:00.000000Z',
            'location': 'Online', 'event_type': 'workshop',
            'source_url': CLUB_URL + '/events/workshop', 'publication_status': 'published',
            'availability_state': 'open', 'requires_membership': None,
            'first_seen_utc': STAMP, 'last_seen_utc': observed, 'source_missing': False,
        }],
    }


class PublicApiDataTests(unittest.TestCase):
    """Use actual temporary SQLite files while replacing only the existing network importer."""

    def setUp(self):
        """Give every source and runtime path a separate disposable temporary location."""
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.folder = Path(temporary.name)
        self.seed = self.folder / 'public' / 'seed.json'
        self.seed.parent.mkdir()
        self.path = self.folder / 'cache' / 'uniclubs.sqlite'
        self.state = {}
        paths = patch.multiple(
            config, DATA_DIR=self.folder, UNICLUBS_EXPORT_FILE=self.seed,
            DB_FILE=self.folder / 'private-app.sqlite',
            UNICLUBS_DB_FILE=self.folder / 'source.sqlite',
            UNICLUBS_USER_DB_FILE=self.folder / 'user.sqlite',
            UNICLUBS_SQLITE=self.folder / 'public' / 'uniclubs.sqlite',
            PUBLIC_UNISPORT_SEED=self.folder / 'public' / 'unisport.sqlite')
        paths.start()
        self.addCleanup(paths.stop)
        self.write_seed(public_snapshot())

    def write_seed(self, document):
        """Replace the fictional checked-in JSON used by this test's cold start."""
        self.seed.write_text(json.dumps(document), encoding='utf-8')

    def ensure(self, now=NOW, refresh=True):
        """Call the production helper with the same factory-owned state on every request."""
        return public_api_data.ensure_uniclubs(self.path, self.state, refresh, now)

    def read_cache(self):
        """Read the durable public document and exact success count after closing the writer."""
        connection = uniclubs_database.get_connection(self.path)
        try:
            document = uniclubs_export.build_export(connection)
            successes = connection.execute('''SELECT COUNT(*) FROM import_log
                WHERE status='success' ''').fetchone()[0]
            return document, successes
        finally:
            connection.close()

    def test_offline_bootstrap_preserves_public_sql_relationships_and_unknown_values(self):
        """Reviewed JSON alone must support a cold API start without any HTTP attempt."""
        with patch(FETCH_TARGET) as fetch:
            result = self.ensure(refresh=False)
        fetch.assert_not_called()
        document, successes = self.read_cache()
        self.assertEqual(document['clubs'][0]['id'], 7)
        self.assertEqual(document['events'][0]['id'], 37)
        self.assertEqual(document['events'][0]['club_id'], 7)
        self.assertIsNone(document['events'][0]['requires_membership'])
        self.assertEqual(successes, 1)
        self.assertEqual(result, {'available': True, 'source_success_utc': STAMP,
                                 'refresh_ok': False, 'stale': False,
                                 'checked_at_utc': None, 'changed': False})
        json.dumps(result)

    def test_newer_feed_updates_and_appends_without_duplicate_rows_or_success_logs(self):
        """An ordinary request checks the network even when the bundled snapshot is fresh."""
        self.ensure(refresh=False)
        document = public_snapshot(NEXT_STAMP)
        document['events'][0]['title'] = 'Rescheduled workshop'
        added = dict(document['events'][0])
        added.update(id=92, external_id='event-2', title='New public event',
                     source_url=CLUB_URL + '/events/new-event', first_seen_utc=NEXT_STAMP)
        document['events'].append(added)
        with patch(FETCH_TARGET, return_value=document) as fetch:
            updated = self.ensure()
            repeated = self.ensure(now=NOW + timedelta(seconds=300))
        self.assertEqual(fetch.call_count, 2)
        self.assertTrue(updated['changed'])
        self.assertTrue(updated['refresh_ok'])
        self.assertFalse(repeated['changed'])
        saved, successes = self.read_cache()
        self.assertEqual([event['id'] for event in saved['events']], [37, 92])
        self.assertEqual(saved['events'][0]['title'], 'Rescheduled workshop')
        self.assertEqual(saved['events'][0]['first_seen_utc'], STAMP)
        self.assertEqual(saved['events'][0]['last_seen_utc'], NEXT_STAMP)
        self.assertEqual(updated['source_success_utc'], NEXT_STAMP)
        self.assertEqual(successes, 2)

    def test_http_failures_keep_last_data_and_cached_failure_metadata(self):
        """A recent failed check cannot make an old source observation appear fresh."""
        self.ensure(refresh=False)
        before = self.read_cache()
        late = NOW + timedelta(hours=2)
        with patch(FETCH_TARGET, side_effect=ValueError('Synthetic HTTP failure')) as fetch:
            failed = self.ensure(now=late)
            cached = self.ensure(now=late + timedelta(seconds=299))
        self.assertEqual(fetch.call_count, 1)
        self.assertEqual(self.read_cache(), before)
        self.assertFalse(failed['refresh_ok'])
        self.assertTrue(failed['stale'])
        self.assertEqual(failed['source_success_utc'], STAMP)
        self.assertEqual(cached['checked_at_utc'], failed['checked_at_utc'])
        self.assertFalse(cached['refresh_ok'])
        self.assertFalse(cached['changed'])

    def test_cold_start_uses_reviewed_json_when_the_first_http_download_fails(self):
        """A network failure on the first request must still leave the public seed usable."""
        with patch(FETCH_TARGET, side_effect=ValueError('Synthetic offline server')) as fetch:
            result = self.ensure()
        fetch.assert_called_once_with()
        self.assertTrue(result['available'])
        self.assertFalse(result['refresh_ok'])
        self.assertEqual(result['source_success_utc'], STAMP)
        self.assertEqual(len(self.read_cache()[0]['events']), 1)

    def test_refresh_bound_is_300_seconds_and_offline_calls_do_not_consume_it(self):
        """Offline startup must leave the first HTTP check due and honor the exact TTL edge."""
        with patch(FETCH_TARGET, return_value=public_snapshot()) as fetch:
            self.ensure(refresh=False)
            first = self.ensure()
            cached = self.ensure(now=NOW + timedelta(seconds=299))
            offline = self.ensure(now=NOW + timedelta(seconds=300), refresh=False)
            self.assertEqual(fetch.call_count, 1)
            next_check = self.ensure(now=NOW + timedelta(seconds=300))
        self.assertEqual(fetch.call_count, 2)
        self.assertEqual(cached['checked_at_utc'], first['checked_at_utc'])
        self.assertEqual(offline['checked_at_utc'], first['checked_at_utc'])
        self.assertNotEqual(next_check['checked_at_utc'], first['checked_at_utc'])

    def test_staleness_uses_source_age_even_during_cached_success(self):
        """A successful HTTP check retains the publisher's timestamp as it crosses the horizon."""
        boundary = datetime(2026, 11, 21, 12, 30, tzinfo=timezone.utc)
        with patch(FETCH_TARGET, return_value=public_snapshot()) as fetch:
            fresh = self.ensure(now=boundary)
            stale = self.ensure(now=boundary + timedelta(seconds=1))
        fetch.assert_called_once_with()
        self.assertFalse(fresh['stale'])
        self.assertTrue(stale['stale'])
        self.assertTrue(stale['refresh_ok'])
        self.assertEqual(stale['source_success_utc'], STAMP)

    def test_state_is_scoped_to_each_cache_and_new_factory_checks_once(self):
        """Reusing state for another cache must not suppress that cache's first HTTP check."""
        with patch(FETCH_TARGET, return_value=public_snapshot()) as fetch:
            self.ensure()
            other_path = self.folder / 'other-cache.sqlite'
            public_api_data.ensure_uniclubs(other_path, self.state, now=NOW)
            public_api_data.ensure_uniclubs(self.path, {}, now=NOW)
        self.assertEqual(fetch.call_count, 3)

    def test_valid_empty_snapshot_is_not_rebootstrapped_from_a_later_seed(self):
        """A success log makes a zero-event source observation a legitimate established cache."""
        document = public_snapshot()
        document['clubs'] = []
        document['events'] = []
        self.write_seed(document)
        self.ensure(refresh=False)
        self.write_seed(public_snapshot(NEXT_STAMP))
        self.ensure(refresh=False)
        saved, successes = self.read_cache()
        self.assertEqual(saved['events'], [])
        self.assertEqual(saved['clubs'], [])
        self.assertEqual(saved['_meta']['last_success_utc'], STAMP)
        self.assertEqual(successes, 1)

    def test_corrupt_or_invalid_json_does_not_leave_a_new_cache(self):
        """Seed validation must complete before a new database is created."""
        for content in ('not JSON', json.dumps({'_meta': {}})):
            with self.subTest(content=content):
                self.seed.write_text(content, encoding='utf-8')
                with patch(FETCH_TARGET) as fetch:
                    with self.assertRaises(ValueError):
                        self.ensure()
                fetch.assert_not_called()
                self.assertFalse(self.path.exists())

    def test_existing_cache_survives_missing_or_corrupted_bundled_json(self):
        """Established caches must not depend on reloading the bundle on every request."""
        self.ensure(refresh=False)
        original = self.read_cache()
        self.seed.write_text('corrupt replacement', encoding='utf-8')
        self.assertTrue(self.ensure(refresh=False)['available'])
        self.seed.unlink()
        self.assertTrue(self.ensure(refresh=False)['available'])
        self.assertEqual(self.read_cache(), original)

    def test_dangerous_targets_and_symlink_or_hardlink_aliases_are_refused(self):
        """Cache initialization must never change runtime databases or distributed seeds."""
        paths = (config.DB_FILE, config.UNICLUBS_DB_FILE, config.UNICLUBS_USER_DB_FILE,
                 config.UNICLUBS_SQLITE, config.PUBLIC_UNISPORT_SEED, self.seed)
        for number, path in enumerate(paths):
            if path != self.seed:
                path.write_bytes(b'private-marker')
            original = path.read_bytes()
            symlink = self.folder / f'symlink-{number}.sqlite'
            symlink.symlink_to(path)
            hardlink = self.folder / f'hardlink-{number}.sqlite'
            hardlink.hardlink_to(path)
            for target in (path, symlink, hardlink):
                with self.subTest(target=target):
                    with self.assertRaises(ValueError):
                        public_api_data.ensure_uniclubs(target, refresh=False, now=NOW)
                    self.assertEqual(path.read_bytes(), original)
        with self.assertRaises(ValueError):
            public_api_data.ensure_uniclubs(self.seed.parent / 'new.sqlite', now=NOW)

    def test_private_source_tables_and_columns_are_never_copied(self):
        """Only public JSON fields may enter a fresh cache even if a source has private data."""
        source = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
        try:
            uniclubs_database.init_db(source)
            uniclubs_export.restore_export(source, public_snapshot())
            with source:
                source.execute('ALTER TABLE events ADD COLUMN private_note TEXT')
                source.execute('UPDATE events SET private_note=?', ('private-marker',))
                source.execute('CREATE TABLE private_people (name TEXT)')
                source.execute('INSERT INTO private_people VALUES (?)', ('private-owner',))
        finally:
            source.close()
        document = public_snapshot()
        document['events'][0]['private_note'] = 'json-private-marker'
        document['private_people'] = [{'name': 'json-private-owner'}]
        self.write_seed(document)
        self.ensure(refresh=False)
        connection = uniclubs_database.get_connection(self.path)
        try:
            columns = [row[1] for row in connection.execute('PRAGMA table_info(events)')]
            tables = [row[0] for row in connection.execute(
                "SELECT name FROM sqlite_master WHERE type='table'")]
        finally:
            connection.close()
        self.assertNotIn('private_note', columns)
        self.assertEqual(set(tables), {'clubs', 'events', 'import_log'})
        self.assertNotIn(b'private-marker', self.path.read_bytes())
        self.assertNotIn(b'private-owner', self.path.read_bytes())

    def test_arbitrary_existing_private_database_is_refused_without_changes(self):
        """A caller-owned database cannot become a cache merely by passing an unknown path."""
        self.path.parent.mkdir()
        connection = sqlite3.connect(self.path)
        with connection:
            connection.execute('CREATE TABLE private_people (name TEXT)')
            connection.execute('INSERT INTO private_people VALUES (?)', ('private-owner',))
        connection.close()
        before = self.path.read_bytes()
        with self.assertRaises(ValueError):
            self.ensure(refresh=False)
        self.assertEqual(self.path.read_bytes(), before)

    def test_invalid_clock_is_rejected_before_any_file_is_created(self):
        """Even an offline request requires an aware datetime for honest UTC freshness."""
        for now in (datetime(2026, 11, 21, 12, 0), '2026-11-21', 1):
            with self.subTest(now=now):
                with self.assertRaises(ValueError):
                    self.ensure(now=now, refresh=False)
                self.assertFalse(self.path.exists())
